/* From Uiverse.io by aadium - Tags: checkbox */
/* Hide the default checkbox */
.__UIV_SCOPE__ .container input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.__UIV_SCOPE__ .container {
  display: block;
  position: relative;
  cursor: pointer;
  font-size: 20px;
  user-select: none;
}

/* Create a custom checkbox */
.__UIV_SCOPE__ .checkmark {
  position: relative;
  height: 70px;
  width: 70px;
  border-radius: 10em;
  background-color: #212121;
  transition: 0.3s;
  box-shadow: 6px 6px 10px #000000,
  -6px -6px 10px #3c3c3c;
}

.__UIV_SCOPE__ .checkmark svg {
  width: 45px;
  height: 45px;
  margin-top: 11px;
  margin-left: 12.5px;
  fill: #264d39;
  transition: 0.2s;
}

.__UIV_SCOPE__ .checkmark:active {
  box-shadow: 2px 2px 3px #000000,
  -2px -2px 3px #3c3c3c;
}

/* When the checkbox is checked */
.__UIV_SCOPE__ .container input:checked ~ .checkmark {
  box-shadow: 4px 4px 6px #000000,
  -4px -4px 6px #3c3c3c;
}

.__UIV_SCOPE__ .container input:checked ~ .checkmark svg {
  fill: #00ff7b;
}

.__UIV_SCOPE__ .container input:checked ~ .checkmark:active {
  box-shadow: 2px 2px 3px #000000,
  -2px -2px 3px #3c3c3c;
}
